// Full-page HTML shell: doctype, head (fonts, meta, SEO), header/nav, main, footer, scripts.

import { existsSync } from "node:fs";
import { join } from "node:path";
import { escapeHtml } from "./html.mjs";
import { nav, footer } from "./components.mjs";

const GENERATED_COMMENT =
  "<!-- Generated by scripts/build.mjs from data/*.json — edit templates in scripts/build/, not this file -->";

function canonicalUrl(ctx) {
  try {
    return new URL(ctx.outPath, ctx.config.siteUrl).toString();
  } catch {
    return null;
  }
}

export function page(ctx, { title, description, bodyHtml, headExtra = "", bodyClassName = "", schema = null, scripts = [] }) {
  const fullTitle = title ? `${title} · ${ctx.config.siteName}` : ctx.config.siteName;
  const desc = description || ctx.config.description;
  const canonical = canonicalUrl(ctx);
  const ogTags = canonical
    ? `<meta property="og:title" content="${escapeHtml(fullTitle)}">
  <meta property="og:description" content="${escapeHtml(desc)}">
  <meta property="og:url" content="${escapeHtml(canonical)}">
  <meta property="og:type" content="website">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${escapeHtml(fullTitle)}">
  <meta name="twitter:description" content="${escapeHtml(desc)}">`
    : "";
  const canonicalTag = canonical ? `<link rel="canonical" href="${escapeHtml(canonical)}">` : "";
  const schemaTag = schema ? `<script type="application/ld+json">${JSON.stringify(schema)}</script>` : "";
  // The favicon is produced by converting V-01 (visual brief) — only link it once it exists on disk,
  // so a missing asset never causes a 404 in the console.
  const faviconPath = "img/icons/favicon.svg";
  const faviconTag = existsSync(join(ctx.projectRoot, faviconPath))
    ? `<link rel="icon" href="${ctx.assetRel}${faviconPath}" type="image/svg+xml">`
    : "";
  // Page-specific enhancement modules (timeline.js, glossary.js, compare.js) — additive, after
  // main.js, so a page without JS-only widgets never pays for them.
  const extraScriptTags = scripts
    .map((src) => `<script type="module" src="${ctx.assetRel}${escapeHtml(src)}"></script>`)
    .join("\n");

  return `${GENERATED_COMMENT}
<!DOCTYPE html>
<html lang="${ctx.config.lang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(fullTitle)}</title>
<meta name="description" content="${escapeHtml(desc)}">
${canonicalTag}
${ogTags}
${faviconTag}
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&amp;family=Inter:wght@400;600&amp;display=swap" rel="stylesheet">
<link rel="stylesheet" href="${ctx.assetRel}css/style.css">
${headExtra}
${schemaTag}
</head>
<body class="${bodyClassName}">
${nav(ctx)}
<main id="main-content">
${bodyHtml}
</main>
${footer(ctx)}
<script type="module" src="${ctx.assetRel}js/main.js"></script>
${extraScriptTags}
</body>
</html>
`;
}

export { GENERATED_COMMENT };
